const customers = $input.all().map(i => i.json);
if (!customers.length || !customers[0].id) return [{ json: { no_data: true } }];

const atRisk = [];
const healthy = [];

for (const c of customers) {
  const activities30d = parseInt(c.activities_30d) || 0;
  const activitiesPrev30d = parseInt(c.activities_prev_30d) || 0;
  const opens30d = parseInt(c.opens_30d) || 0;
  const opensPrev30d = parseInt(c.opens_prev_30d) || 0;
  const lastActivity = c.last_activity ? new Date(c.last_activity) : null;
  const daysSinceActivity = lastActivity ? (Date.now() - lastActivity.getTime()) / (1000*60*60*24) : 999;

  // Churn risk scoring
  let churnRisk = 0;
  const signals = [];

  // Activity decline
  if (activitiesPrev30d > 0 && activities30d < activitiesPrev30d * 0.5) {
    churnRisk += 25;
    signals.push(`Activity dropped ${Math.round((1 - activities30d/activitiesPrev30d) * 100)}%`);
  }

  // Email engagement decline
  if (opensPrev30d > 0 && opens30d < opensPrev30d * 0.5) {
    churnRisk += 20;
    signals.push('Email engagement declining');
  }

  // Inactivity
  if (daysSinceActivity > 30) {
    churnRisk += 20;
    signals.push(`No activity for ${Math.round(daysSinceActivity)} days`);
  } else if (daysSinceActivity > 14) {
    churnRisk += 10;
    signals.push(`Low activity (${Math.round(daysSinceActivity)} days since last)`);
  }

  // Zero engagement this month
  if (activities30d === 0) {
    churnRisk += 25;
    signals.push('Zero engagement this month');
  }

  // No email opens
  if (opens30d === 0 && opensPrev30d > 0) {
    churnRisk += 10;
    signals.push('Stopped opening emails');
  }

  const riskLevel = churnRisk >= 60 ? 'high' : churnRisk >= 30 ? 'medium' : 'low';

  if (churnRisk >= 30) {
    atRisk.push({
      contact_id: c.id,
      email: c.email,
      name: `${c.first_name} ${c.last_name}`,
      company: c.company,
      deal_value: parseFloat(c.deal_value) || 0,
      assigned_to: c.assigned_to,
      churn_risk: churnRisk,
      risk_level: riskLevel,
      signals: signals,
      days_since_activity: Math.round(daysSinceActivity),
      recommended_action: churnRisk >= 60 ? 'Immediate outreach - schedule call' :
                          churnRisk >= 40 ? 'Send personalized check-in email' :
                          'Monitor closely, send value content'
    });
  } else {
    healthy.push(c.id);
  }
}

const totalAtRisk = atRisk.reduce((s, c) => s + c.deal_value, 0);

return [{
  json: {
    summary: {
      total_customers: customers.length,
      at_risk: atRisk.length,
      healthy: healthy.length,
      high_risk: atRisk.filter(c => c.risk_level === 'high').length,
      medium_risk: atRisk.filter(c => c.risk_level === 'medium').length,
      revenue_at_risk: totalAtRisk
    },
    at_risk_customers: atRisk.sort((a, b) => b.churn_risk - a.churn_risk).slice(0, 20),
    generated_at: new Date().toISOString()
  }
}];

